query SearchTodos($searchTerm: String!, $category: String, $priority: String, $status: String) {
  searchNodes(
    query: $searchTerm
    tableId: "58"
    filters: [
      { attributeName: "category", value: $category }
      { attributeName: "priority", value: $priority }
      { attributeName: "status", value: $status }
    ]
  ) {
    nodes {
      id
      content
      attributes {
        name
        value
      }
      relevanceScore
    }
    totalMatches
  }
}
